-- Sprint 49 — workflows inteligentes, SLA, notificações, automações e agenda (PostgreSQL 15+)
create schema if not exists automation;
alter table operations.workflow_definitions add column if not exists code varchar(80), add column if not exists status varchar(20) not null default 'DRAFT', add column if not exists current_version int not null default 1, add column if not exists deleted_at timestamptz;
alter table operations.workflow_steps add column if not exists step_type varchar(30) not null default 'TASK', add column if not exists due_minutes int, add column if not exists entry_condition jsonb not null default '{}', add column if not exists exit_condition jsonb not null default '{}', add column if not exists expected_action varchar(1000), add column if not exists required boolean not null default true, add column if not exists delegation_allowed boolean not null default false, add column if not exists evidence_required boolean not null default false;
create table if not exists operations.workflow_versions(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenancy.tenants(id),definition_id uuid not null,version int not null check(version>0),status varchar(20) not null check(status in('DRAFT','ACTIVE','INACTIVE')),published_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid not null references identity.users(id),updated_by uuid references identity.users(id),deleted_at timestamptz,foreign key(tenant_id,definition_id) references operations.workflow_definitions(tenant_id,id),unique(tenant_id,definition_id,version));
create table if not exists operations.workflow_instance_events(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenancy.tenants(id),instance_id uuid not null,event_type varchar(40) not null,previous_status varchar(20),new_status varchar(20),comment varchar(2000),evidence_key varchar(500),details jsonb not null default '{}',created_at timestamptz not null default now(),created_by uuid not null references identity.users(id),foreign key(tenant_id,instance_id) references operations.workflow_instances(tenant_id,id));
create table if not exists operations.workflow_task_comments(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenancy.tenants(id),task_id uuid not null,comment varchar(3000) not null check(length(trim(comment))>0),evidence_key varchar(500),created_at timestamptz not null default now(),created_by uuid not null references identity.users(id),foreign key(tenant_id,task_id) references operations.operational_tasks(tenant_id,id));
create table if not exists operations.notification_templates(id uuid primary key default gen_random_uuid(),tenant_id uuid references tenancy.tenants(id),name varchar(160) not null,code varchar(80) not null,culture varchar(5) not null check(culture in('pt-BR','en-US','es-ES')),subject varchar(300),body text not null,channel varchar(20) not null check(channel in('INTERNAL','EMAIL','WHATSAPP','WEBHOOK')),allowed_variables text[] not null default '{}',status varchar(20) not null check(status in('DRAFT','ACTIVE','INACTIVE')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid not null references identity.users(id),updated_by uuid references identity.users(id),deleted_at timestamptz,unique(tenant_id,code,culture,channel),check(status<>'ACTIVE' or length(trim(body))>0),check(channel='INTERNAL' or length(trim(subject))>0));
create table if not exists operations.notification_outbox(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenancy.tenants(id),template_id uuid,channel varchar(20) not null check(channel in('EMAIL','WHATSAPP','WEBHOOK')),recipient varchar(254) not null,payload jsonb not null,status varchar(30) not null default 'PENDING_NOT_CONFIGURED' check(status in('PENDING','PENDING_NOT_CONFIGURED','PROCESSING','SENT','FAILED')),provider varchar(80),attempts int not null default 0,last_error varchar(2000),attempted_at timestamptz,sent_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid not null references identity.users(id),updated_by uuid references identity.users(id),foreign key(template_id) references operations.notification_templates(id),check(status<>'SENT' or sent_at is not null));
create table if not exists operations.sla_policies(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenancy.tenants(id),name varchar(160) not null,module varchar(50) not null,occurrence_type varchar(60) not null,priority varchar(16) not null check(priority in('LOW','MEDIUM','HIGH','CRITICAL')),due_minutes int not null check(due_minutes>0),initial_responsible_id uuid,manager_id uuid,timezone varchar(80) not null default 'America/Sao_Paulo',overdue_action varchar(40) not null,status varchar(20) not null check(status in('ACTIVE','INACTIVE')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid not null references identity.users(id),updated_by uuid references identity.users(id),deleted_at timestamptz,unique(tenant_id,module,occurrence_type,priority));
create table if not exists operations.sla_escalations(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenancy.tenants(id),policy_id uuid not null,task_id uuid,workflow_instance_id uuid,escalated_to uuid not null,reason varchar(1000) not null,escalated_at timestamptz not null default now(),created_at timestamptz not null default now(),created_by uuid not null references identity.users(id),foreign key(tenant_id,policy_id) references operations.sla_policies(tenant_id,id),check(task_id is not null or workflow_instance_id is not null));
create table if not exists automation.rules(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenancy.tenants(id),name varchar(160) not null,trigger_type varchar(40) not null,condition_json jsonb not null,action_type varchar(40) not null,action_config jsonb not null default '{}',source_module varchar(50) not null,target_module varchar(50),status varchar(20) not null check(status in('DRAFT','ACTIVE','INACTIVE')),critical boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid not null references identity.users(id),updated_by uuid references identity.users(id),deleted_at timestamptz,unique(tenant_id,name),check(status<>'ACTIVE' or condition_json<>'{}'::jsonb));
create table if not exists automation.executions(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenancy.tenants(id),rule_id uuid not null,idempotency_key varchar(200) not null,status varchar(20) not null check(status in('PROCESSING','COMPLETED','FAILED','SKIPPED')),source_entity_type varchar(80),source_entity_id uuid,result jsonb,error varchar(2000),started_at timestamptz not null default now(),completed_at timestamptz,created_at timestamptz not null default now(),created_by uuid references identity.users(id),foreign key(tenant_id,rule_id) references automation.rules(tenant_id,id),unique(tenant_id,rule_id,idempotency_key));
create table if not exists operations.agenda_events(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenancy.tenants(id),title varchar(200) not null,event_type varchar(40) not null,module varchar(50) not null,responsible_id uuid,starts_at timestamptz not null,ends_at timestamptz,timezone varchar(80) not null,visibility varchar(20) not null default 'TENANT',status varchar(20) not null check(status in('SCHEDULED','COMPLETED','CANCELLED')),cancellation_reason varchar(1000),related_entity_type varchar(80),related_entity_id uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid not null references identity.users(id),updated_by uuid references identity.users(id),deleted_at timestamptz,check(ends_at is null or ends_at>starts_at),check(status<>'CANCELLED' or length(trim(cancellation_reason))>0));
create table if not exists operations.workflow_report_exports(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenancy.tenants(id),report_type varchar(60) not null,filters jsonb not null default '{}',status varchar(20) not null,storage_key varchar(500),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid not null references identity.users(id),updated_by uuid references identity.users(id));
create index if not exists ix_workflow_versions_tenant_status on operations.workflow_versions(tenant_id,status,definition_id,version desc);
create index if not exists ix_workflow_events_tenant_instance on operations.workflow_instance_events(tenant_id,instance_id,created_at desc);
create index if not exists ix_notification_templates_lookup on operations.notification_templates(tenant_id,status,code,culture,channel) where deleted_at is null;
create index if not exists ix_notification_outbox_delivery on operations.notification_outbox(tenant_id,status,channel,created_at);
create index if not exists ix_sla_policy_lookup on operations.sla_policies(tenant_id,status,module,occurrence_type,priority) where deleted_at is null;
create index if not exists ix_sla_escalations_audit on operations.sla_escalations(tenant_id,escalated_at desc,escalated_to);
create index if not exists ix_automation_rules_trigger on automation.rules(tenant_id,status,source_module,trigger_type) where deleted_at is null;
create index if not exists ix_automation_executions_status on automation.executions(tenant_id,status,started_at desc);
create index if not exists ix_agenda_range on operations.agenda_events(tenant_id,starts_at,status,responsible_id) where deleted_at is null;
do $$ declare item text; begin foreach item in array array['workflow_versions','workflow_instance_events','workflow_task_comments','notification_templates','notification_outbox','sla_policies','sla_escalations','agenda_events','workflow_report_exports'] loop execute format('alter table operations.%I enable row level security',item); execute format('drop policy if exists tenant_isolation on operations.%I',item); execute format('create policy tenant_isolation on operations.%I using (tenant_id=platform.current_tenant_id()) with check (tenant_id=platform.current_tenant_id())',item); end loop; end $$;
do $$ declare item text; begin foreach item in array array['rules','executions'] loop execute format('alter table automation.%I enable row level security',item); execute format('drop policy if exists tenant_isolation on automation.%I',item); execute format('create policy tenant_isolation on automation.%I using (tenant_id=platform.current_tenant_id()) with check (tenant_id=platform.current_tenant_id())',item); end loop; end $$;
insert into platform.schema_versions(version,description) values('4.9.0','Sprint 49 - workflows, tarefas, notificações, SLA, automação e agenda') on conflict(version) do nothing;
